// Package cryptoutil holds the primitive crypto the Digitral apps use. Every
// function here is a port of a helper in scripts/bima_balance.py and is pinned
// by testdata/crypto_vectors.json, which was generated by that Python code.
package cryptoutil

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/sha512"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"
)

// SHA512Hex is sha512_hex: lowercase hex of the SHA-512 over the UTF-8 bytes.
func SHA512Hex(s string) string {
	h := sha512.Sum512([]byte(s))
	return hex.EncodeToString(h[:])
}

// GetValues is MixUpValues.getValues: every other character, 1-based odd
// positions. Python slices the string by code point, so this iterates runes
// rather than bytes.
func GetValues(s string) string {
	r := []rune(s)
	var b strings.Builder
	for i := 0; i < len(r); i += 2 {
		b.WriteRune(r[i])
	}
	return b.String()
}

// RC4Hex is ODPRC4: RC4 over the key schedule built from the key's characters,
// XORed with each rune of text, output as lowercase hex of the low byte.
// crypto/rc4 operates on bytes and would differ for non-ASCII input, so the
// schedule is implemented here to match the app exactly.
func RC4Hex(key, text string) string {
	if key == "" {
		return ""
	}
	k := make([]int, 256)
	kr := []rune(key)
	for i := range k {
		k[i] = int(kr[i%len(kr)])
	}
	box := make([]int, 256)
	for i := range box {
		box[i] = i
	}
	j := 0
	for i := 0; i < 256; i++ {
		j = (j + box[i] + k[i]) % 256
		box[i], box[j] = box[j], box[i]
	}
	var b strings.Builder
	i, j := 0, 0
	for _, r := range text {
		i = (i + 1) % 256
		j = (j + box[i]) % 256
		box[i], box[j] = box[j], box[i]
		b.WriteString(fmt.Sprintf("%02x", (box[(box[i]+box[j])%256]^int(r))&0xFF))
	}
	return b.String()
}

// AESGCMEncrypt is ODPAESEncryption.encryptNew: AES-256-GCM with a static IV,
// empty AAD, output base64(ciphertext+tag) with no line wrapping.
func AESGCMEncrypt(key, iv, plaintext []byte) (string, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}
	// The app passes a 16-byte IV; Go's default GCM nonce is 12, so the nonce
	// size is taken from the IV to match cryptography's modes.GCM(iv).
	aead, err := cipher.NewGCMWithNonceSize(block, len(iv))
	if err != nil {
		return "", err
	}
	ct := aead.Seal(nil, iv, plaintext, []byte{})
	return base64.StdEncoding.EncodeToString(ct), nil
}

// JWTExp returns the exp claim of a JWT in seconds, or 0 when it cannot be read.
func JWTExp(jwt string) int64 {
	parts := strings.Split(jwt, ".")
	if len(parts) < 2 {
		return 0
	}
	p := parts[1]
	p += strings.Repeat("=", (4-len(p)%4)%4)       // Python-style non-negative modulo
	raw, err := base64.URLEncoding.DecodeString(p) // padded, like python urlsafe_b64decode
	if err != nil {
		return 0
	}
	var claim struct {
		Exp any `json:"exp"`
	}
	if err := json.Unmarshal(raw, &claim); err != nil {
		return 0
	}
	switch v := claim.Exp.(type) {
	case float64:
		return int64(v)
	case string:
		var n int64
		if _, err := fmt.Sscanf(v, "%d", &n); err == nil {
			return n
		}
	}
	return 0
}
